using System;using System.Collections;using System.Collections.Generic;using System.Globalization;using System.IO;using System.Linq;using System.Text;using System.Text.RegularExpressions;
namespace PZ3D {
 sealed class UpdateAnnouncementView {public int schema=1;public string version,date="",body="",warning="";public bool available,unread=true;}
 // Notes travel with the executing core, never the update candidate or an old installation directory.
 sealed class UpdateAnnouncementService {
  readonly string data,version,notes;const int MaxNotes=2097152;
  internal UpdateAnnouncementService(string data,string version,string notes){this.data=Path.GetFullPath(data);CoreReleaseProtocol.ParseVersion(version);this.version=version;this.notes=notes;}
  internal static UpdateAnnouncementService Current(string data){string notes=null;try{using(var input=typeof(UpdateAnnouncementService).Assembly.GetManifestResourceStream("Launcher.Changelog.md")){if(input!=null&&input.Length<=MaxNotes)using(var reader=new StreamReader(input,new UTF8Encoding(false,true)))notes=reader.ReadToEnd();}}catch(IOException){}catch(DecoderFallbackException){}return new UpdateAnnouncementService(data,AppVersion.Current,notes);}
  string PreferencePath {get{return Path.Combine(data,"user-settings","update-announcements.json");}}
  HashSet<string> ReadVersions(){var value=LauncherNativeState.Read<Dictionary<string,object>>(PreferencePath,()=>null);var versions=new HashSet<string>(StringComparer.Ordinal);if(value==null){if(File.Exists(PreferencePath))throw new IOException("更新公告阅读记录无效，原文件已保留。");return versions;}object schema,read;if(value.Count!=2||!value.TryGetValue("schema",out schema)||!(schema is int)||(int)schema!=1||!value.TryGetValue("readVersions",out read)||!(read is IEnumerable)||read is string)throw new IOException("更新公告阅读记录无效，原文件已保留。");foreach(var item in (IEnumerable)read){string saved=item as string;if(saved==null)throw new IOException("更新公告阅读记录无效，原文件已保留。");try{CoreReleaseProtocol.ParseVersion(saved);}catch{throw new IOException("更新公告阅读记录无效，原文件已保留。");}versions.Add(saved);}return versions;}
  UpdateAnnouncementView Content(){var value=new UpdateAnnouncementView{version=version};if(notes==null||notes.Length>MaxNotes){value.warning="当前安装包暂时无法读取本版本的更新说明，可稍后在帮助中重试。";return value;}string[] lines=notes.Replace("\r\n","\n").Replace('\r','\n').Split('\n');var header=new Regex(@"^##\s+"+Regex.Escape(version)+@"\s+[—-]\s+(?<date>\d{4}-\d{2}-\d{2})\s*$");int start=-1;for(int i=0;i<lines.Length;i++)if(header.IsMatch(lines[i])){if(start>=0){value.warning="当前安装包中的本版本更新说明不完整，可稍后在帮助中重试。";return value;}start=i;}DateTime date;if(start<0||!DateTime.TryParseExact(header.Match(lines[start]).Groups["date"].Value,"yyyy-MM-dd",CultureInfo.InvariantCulture,DateTimeStyles.None,out date)){value.warning="当前安装包暂未包含本版本的更新说明，可稍后在帮助中重试。";return value;}int end=start+1;while(end<lines.Length&&!Regex.IsMatch(lines[end],@"^##\s+"))end++;value.body=string.Join("\n",lines.Skip(start+1).Take(end-start-1)).Trim();if(value.body.Length==0){value.warning="当前安装包暂未包含本版本的更新正文，可稍后在帮助中重试。";return value;}value.date=date.ToString("yyyy-MM-dd",CultureInfo.InvariantCulture);value.available=true;return value;}
  internal UpdateAnnouncementView Get(){var value=Content();try{value.unread=!ReadVersions().Contains(version);}catch(Exception){value.warning=(value.warning.Length==0?"":value.warning+" ")+"更新公告的阅读记录暂时无法读取，原文件已保留；不影响使用启动器。";}return value;}
  internal UpdateAnnouncementView Dismiss(){if(!Content().available)throw new IOException("本版本更新说明尚未读取，未记录为已读。");return LauncherNativeState.Locked(PreferencePath,()=>{var versions=ReadVersions();if(versions.Add(version))LauncherNativeState.Write(PreferencePath,new{schema=1,readVersions=versions.OrderBy(item=>item,StringComparer.Ordinal).ToArray()});return Get();});}
 }
}